import {createAtlasUI} from './atlas.js';
import {blankState,LEVELS,localDate,shuffle,filterBank,nextReview,scoreExam,summarize,parseBackup,ROLES,normalizeProfile,resetStudyProgress} from './core.js';

const KEY='orl-estudio-v1';
const APP_ROOT=new URL('./',import.meta.url);
const $=s=>document.querySelector(s);
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4ZM20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3Z',cards:'m7 4 12 3-3 14-12-3ZM10 2l12 4-2 10M9 10l5 1M8 14l5 1',check:'m5 12 4 4L19 6',arrow:'M4 12h15m-5-5 5 5-5 5',back:'M20 12H5m5-5-5 5 5 5',chevron:'m9 5 7 7-7 7',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0M12 11v2',chart:'M4 20V10m6 10V4m6 16v-7m5 7H2',bookmark:'M6 3h12v18l-6-4-6 4Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',close:'m6 6 12 12M6 18 18 6',repeat:'m18 2 4 4-4 4M2 10V8a2 2 0 0 1 2-2h18M6 22l-4-4 4-4m16 0v2a2 2 0 0 1-2 2H2',light:'M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2',shield:'m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5Zm-4 9 3 3 5-6',calendar:'M5 5h14v16H5ZM8 2v6m8-6v6M5 10h14',ear:'M8 17c0 4 5 5 6 1 1-3 5-4 5-9A7 7 0 0 0 5 9m4 2V9a3 3 0 1 1 6 0c0 3-4 3-4 6',anatomy:'M9 22v-4l-4-1V9a7 7 0 0 1 14 0v5l2 1-3 2v5M9 9h.1M14 9h.1M9 13h5',nose:'M10 3v7c0 4-3 4-3 7 0 2 2 3 5 3s5-1 5-3c0-2-2-3-2-5V3M10 17h4',mouth:'M2 12s5-5 10-5 10 5 10 5-4 6-10 6S2 12 2 12Zm0 0h20M9 8l3 4 3-4',neck:'M8 2v7l-4 5v8m12-20v7l4 5v8M8 9h8M9 13h6m-6 4h6',child:'M8 6a4 4 0 1 0 8 0 4 4 0 1 0-8 0M7 22v-7l-4-3m14 10v-7l4-3M7 16h10',layers:'m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm7 0a3 3 0 1 0 6 0 3 3 0 0 0-6 0',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wifi:'M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0m-9 4a5 5 0 0 1 6 0m-3 4h.1',file:'M5 2h9l5 5v15H5Zm9 0v6h5M8 12h8m-8 4h6',spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z'};
const ic=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.book}"/></svg>`;
const topicIcons=['anatomy','ear','ear','nose','mouth','neck','layers','child'];
const accents=['#81966a','#7b9c9b','#a28eac','#c19b73','#ac867d','#8596a9','#849b7f','#be9b72'];
const tints=['#edf1e7','#eaf1ef','#f1edf4','#f7f0e5','#f5eeeb','#edf0f4','#edf1e9','#f7f0e6'];
let atlasCatalog=null;
let bank,byId,state=blankState(),storageAvailable=true,offlineReady=false,deferredInstall=null;
let cfg={type:'card',block:'all',level:'all',pool:'all',count:20,minutes:20};
let filters={block:'all',level:'all',format:'all',pool:'all',search:''};let listPage=1,reviewTab='errors';let toastTimer;
const atlasUI=createAtlasUI({root:APP_ROOT,getCatalog:()=>atlasCatalog,getState:()=>state,persist,shell,ic,toast,startSession,showQuestion,modal,byId:id=>byId?.get(id),references:block=>bank.blocks[block-1].references});
const route=()=>{const [name='home',query='']=(location.hash.slice(1)||'home').split('?');return {name,params:new URLSearchParams(query)};};
const go=hash=>{if(location.hash.slice(1)===hash){render();window.scrollTo(0,0);}else location.hash=hash;};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{const first=storageAvailable;storageAvailable=false;if(first)toast('No se pudo guardar en este navegador. Exporta tu progreso desde Ajustes.');return false;}}
function loadState(){try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);const cleaned=parseBackup({app:'orl-estudio',schema:1,state:parsed},bank.questions);const s=parsed.session;if(validSession(s))cleaned.session=s;state=cleaned;}}catch{storageAvailable=false;}}
function validSession(s){return s&&['card','mcq','exam'].includes(s.type)&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.length<=464&&new Set(s.ids).size===s.ids.length&&s.ids.every(id=>Number.isInteger(id)&&byId.has(id)&&(s.type==='card'||byId.get(id).type==='mcq'))&&Number.isInteger(s.pos)&&s.pos>=0&&s.pos<s.ids.length&&s.answers&&typeof s.answers==='object'&&!Array.isArray(s.answers)&&s.recorded&&typeof s.recorded==='object'&&s.revealed&&typeof s.revealed==='object'&&s.drafts&&typeof s.drafts==='object'&&s.ratings&&typeof s.ratings==='object'&&Number.isFinite(s.started)&&(s.type!=='exam'||Number.isFinite(s.deadline));}
function saveReview(id,kind,correct=null,rating='good'){state.records[id]=nextReview(state.records[id],{kind,correct,rating});const date=localDate();state.activity[date]=(state.activity[date]||0)+1;}
function modal(title,body,buttons=[{label:'Entendido',action:'close-modal',primary:true}]){const d=$('#modal');d.innerHTML=`<h2 id="modal-title">${e(title)}</h2>${body}${buttons.length?`<div class="dialog-actions">${buttons.map(b=>`<button class="btn ${b.primary?'':b.danger?'danger':'secondary'}" data-act="${e(b.action)}">${e(b.label)}</button>`).join('')}</div>`:''}`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();}
function profileInitials(){return state.profile.name?e(state.profile.name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>Array.from(s)[0]).join('').toLocaleUpperCase('es')):ic('anatomy',17);}
function editProfile(firstVisit=false){const profile=state.profile;modal(firstVisit?'Haz tuyo este espacio':'Mi perfil',`<div class="profile-intro"><span class="profile-emblem">${ic('anatomy',26)}</span><p>${firstVisit?'Elige cómo quieres aparecer en ORL Estudio. Puedes usar tu nombre o un alias.':'Personaliza el nombre y los datos que ves mientras estudias.'}</p></div><form id="profile-form"><div class="field"><label for="profile-name">Nombre o alias</label><input id="profile-name" name="profileName" type="text" maxlength="80" autocomplete="nickname" autocapitalize="words" value="${e(profile.name)}" placeholder="Cómo quieres que te llamemos" required></div><div class="field"><label for="profile-role">Etapa de formación <span class="subtle">· opcional</span></label><select id="profile-role" name="profileRole">${opt('','Selecciona tu etapa',profile.role)}${Object.entries(ROLES).map(([v,label])=>opt(v,label,profile.role)).join('')}</select></div><div class="field"><label for="profile-institution">Centro de formación <span class="subtle">· opcional</span></label><input id="profile-institution" name="profileInstitution" type="text" maxlength="120" autocomplete="organization" value="${e(profile.institution)}" placeholder="Universidad, hospital o centro de estudios"></div><p class="profile-note">${ic('shield',15)}<span>Tu perfil y tu progreso se guardan en este navegador. Puedes llevarlos a otro dispositivo con una copia de respaldo.</span></p><p id="profile-error" class="profile-error" role="alert" hidden></p><div class="dialog-actions"><button class="btn secondary" type="button" data-act="${firstVisit?'profile-skip':'close-modal'}">${firstVisit?'Continuar como invitado':'Cancelar'}</button><button class="btn" type="submit">${firstVisit?'Guardar y empezar':'Guardar perfil'} ${ic('check',15)}</button></div></form>`,[]);}
function profileSummary(){return `<section class="panel profile-summary"><div class="profile-heading"><div class="avatar">${profileInitials()}</div><div><h2>Mi perfil</h2><p>${state.profile.name?e(state.profile.name):'Personaliza tu espacio de estudio'}</p></div><button class="btn secondary small" data-act="profile" id="edit-profile">${state.profile.name?'Editar perfil':'Añadir mis datos'}</button></div>${state.profile.name?`<div class="profile-details">${state.profile.role?`<span>${e(ROLES[state.profile.role])}</span>`:''}${state.profile.institution?`<span>${e(state.profile.institution)}</span>`:''}</div>`:''}<p class="hint">Este perfil pertenece a este navegador. Cada persona puede configurar el suyo en su dispositivo; los datos no se sincronizan automáticamente.</p></section>`;}
document.addEventListener('submit',event=>{if(event.target.id!=='profile-form')return;event.preventDefault();try{const profile=normalizeProfile({name:$('#profile-name').value,role:$('#profile-role').value,institution:$('#profile-institution').value});if(!profile.name)throw Error('Escribe tu nombre o un alias.');state.profile=profile;state.profileOnboarded=true;const saved=persist();closeModal();render();toast(saved?'Tu perfil está guardado.':'Perfil actualizado. Exporta una copia para conservarlo.');}catch(error){const el=$('#profile-error');el.hidden=false;el.textContent=error.message;}});
$('#modal').addEventListener('cancel',()=>{if(!state.profileOnboarded){state.profileOnboarded=true;persist();}});
const tag=q=>`<span class="tag ${q.level}">${LEVELS[q.level]}</span>`;
const formatTag=q=>`<span class="tag neutral">${q.type==='mcq'?'Selección simple':'Abierta'}</span>`;
function answerHtml(q){return `<div class="answer-text">${q.answer.map(t=>`<p${/^Opción correcta/.test(t)?' class="key-line"':''}>${e(t)}</p>`).join('')}</div><div class="source"><strong>Fuente del banco</strong>${q.sources.map(e).join('<br>')}<br><button class="text-btn" data-act="references" data-id="${q.block}">Ver referencias completas ${ic('arrow',12)}</button></div>${atlasUI.related(q)}`;}
function navLink(name,title,icon,count){const current=route().name;const active=name===current||(name==='atlas'&&current==='exploration')||(name==='practice'&&['session','result'].includes(current));return `<a href="#${name}" class="${active?'active':''}" ${active?'aria-current="page"':''}>${ic(icon)}<span>${title}</span>${count?`<span class="badge">${count}</span>`:''}</a>`;}
function shell(body,title){const stats=summarize(bank.questions,state);return `<div class="layout"><aside class="sidebar"><a href="#home" class="brand" aria-label="ORL Estudio, inicio"><div class="brand-icon">${ic('ear',25)}</div><div><strong>ORL Estudio<span style="color:#8ca877">.</span></strong><small>Tu próximo paso</small></div></a><div class="nav-label">MI PREPARACIÓN</div><nav class="nav" aria-label="Principal">${navLink('home','Mi inicio','home')}${navLink('practice','Practicar','cards')}${navLink('exam','Simulacro','clock')}${navLink('bank','Banco de preguntas','book')}${navLink('review','Mis repasos','repeat',stats.errors)}${navLink('atlas','Atlas visual','eye')}${navLink('exploration','Exploración física','ear')}${navLink('sheets','Fichas de estudio','layers')}${navLink('progress','Mi progreso','chart')}</nav><div class="side-bottom"><div class="side-tip">${ic('light',20)}<strong>Primero intenta recordarlo.</strong>Responde antes de revelar la solución. Después compara con el banco.</div><a href="#settings">${ic('settings',16)} Ajustes y respaldo</a><button class="owner profile-trigger" data-act="profile" aria-label="Abrir mi perfil"><span class="avatar">${profileInitials()}</span><span class="profile-trigger-copy"><strong>${e(state.profile.name||'Mi perfil')}</strong><small>${e(ROLES[state.profile.role]||'Personaliza tu espacio')}</small></span>${ic('chevron',13)}</button></div></aside><div class="content"><header class="topbar"><div class="breadcrumb"><span>Mi preparación</span>${ic('chevron',11)}<strong>${e(title)}</strong></div><div class="top-actions"><div class="status"><span class="status-dot" style="${!offlineReady?'background:#b4b9a6':''}"></span><span id="offline-status">${offlineReady?'Banco sin conexión':navigator.onLine?'En línea':'Sin conexión'}</span></div><button class="install-btn" data-act="install">${ic('download',13)} Instalar app</button><button class="top-profile avatar" data-act="profile" aria-label="Mi perfil" title="${e(state.profile.name||'Mi perfil')}">${profileInitials()}</button></div></header>${!storageAvailable?'<div class="storage-alert" role="alert">El guardado local no está disponible. Exporta una copia de tu progreso desde Ajustes antes de salir.</div>':''}<main id="main" class="page" tabindex="-1">${body}</main></div><nav class="mobile-nav" aria-label="Navegación móvil">${navLink('home','Inicio','home')}${navLink('practice','Practicar','cards')}${navLink('exam','Simulacro','clock')}${navLink('review','Repasos','repeat')}${navLink('atlas','Atlas','eye')}${navLink('settings','Ajustes','settings')}</nav></div>`;}
function resumeBanner(){const s=state.session;if(!s||s.done)return '';return `<div class="resume-banner"><div><strong>${s.type==='exam'?'Tienes un simulacro en curso':'Tu sesión sigue aquí'}</strong><p>Pregunta ${s.pos+1} de ${s.ids.length}${s.type==='exam'?' · El tiempo continúa corriendo.':''}</p></div><a class="btn small secondary" href="#session">Continuar ${ic('arrow',13)}</a></div>`;}
function topicCard(b){const reviewed=bank.questions.filter(q=>q.block===b.id&&state.records[q.id]?.reviews).length;const pct=Math.round(reviewed/b.count*100);return `<a class="topic-card" href="#practice?block=${b.id}" style="--accent:${accents[b.id-1]};--tint:${tints[b.id-1]}"><div class="topic-card-top"><div class="topic-ico">${ic(topicIcons[b.id-1],21)}</div><span class="topic-num">${String(b.id).padStart(2,'0')}</span></div><h3>${e(b.title)}</h3><p>${b.count} preguntas · ${b.mcq} de selección</p><div class="progress-track"><i style="width:${pct}%"></i></div><div class="topic-foot"><span>${reviewed?'Repasadas '+reviewed+' de '+b.count:'Por descubrir'}</span>${ic('arrow',12)}</div></a>`;}
function home(){const s=summarize(bank.questions,state);const pct=Math.min(100,Math.round(s.today/state.goal*100));const date=new Intl.DateTimeFormat('es',{day:'numeric',month:'long'}).format(new Date());return shell(`<div class="welcome"><div><div class="eyebrow"><span style="width:6px;height:6px;border-radius:50%;background:#90a675"></span>Preparación para el posgrado</div><h1>${state.profile.name?`Hola, ${e(state.profile.name)}.`:'Tu espacio para aprender.'}</h1><p>Cada pregunta es un paso más hacia otorrinolaringología.</p></div><div class="date-pill">${ic('calendar',13)} ${e(date)}</div></div>${resumeBanner()}<div class="dashboard-top"><section class="hero"><div class="hero-kicker">${ic('spark',12)} UNA SESIÓN A LA VEZ</div><h2>Domina cada tema,<br>pregunta a pregunta.</h2><p>${s.due?`Tienes ${s.due} preguntas listas para volver a repasar.`:'Empieza con una sesión breve. Responde, descubre lo que sabes y vuelve a intentarlo.'}</p><a href="#practice${s.due?'?pool=due':''}" class="btn">${ic('cards',15)} ${s.reviewed?'Continuar mi repaso':'Empezar mi repaso'} ${ic('arrow',14)}</a><div class="hero-art" aria-hidden="true"><div class="art-card">${ic('ear',70)}<div class="line"></div></div><div class="art-card">${ic('cards',51)}<div class="line"></div><div class="line" style="width:40px"></div><div class="dots"><i></i><i></i><i></i></div></div></div></section><section class="daily-card"><div class="card-label">Mi meta de hoy <small>Un poco, cada día</small></div><div class="daily-center"><svg class="ring" viewBox="0 0 140 140" aria-hidden="true"><circle class="ring-bg" cx="70" cy="70" r="57"/><circle class="ring-value" cx="70" cy="70" r="57" stroke-dasharray="358.14" stroke-dashoffset="${358.14*(1-pct/100)}"/></svg><div class="ring-copy"><strong>${s.today}<span style="font-size:14px;color:#a2ada0">/${state.goal}</span></strong><small>repasos realizados</small></div></div><p class="daily-foot">${s.today>=state.goal?'<strong>¡Meta alcanzada!</strong> Buen trabajo.':`Te quedan <strong>${state.goal-s.today} repasos</strong> para tu meta.`}</p></section></div><div class="stats-grid"><div class="stat"><div class="stat-icon">${ic('book',18)}</div><div><b>${s.reviewed} <em>/ 464</em></b><span>Preguntas repasadas</span></div></div><div class="stat"><div class="stat-icon">${ic('target',18)}</div><div><b>${s.accuracy===null?'—':s.accuracy+'%'}</b><span>Aciertos en selección</span></div></div><a href="#review" class="stat"><div class="stat-icon">${ic('repeat',18)}</div><div><b>${s.errors}</b><span>Para reforzar</span></div></a><a href="#review?tab=saved" class="stat"><div class="stat-icon">${ic('bookmark',17)}</div><div><b>${s.saved}</b><span>Mis favoritas</span></div></a></div><section><div class="section-head"><div><h2>Explora tus temas</h2><p>8 bloques · 464 preguntas · 3 niveles de dificultad</p></div><a class="text-btn" href="#bank">Ver banco ${ic('arrow',13)}</a></div><div class="topic-grid">${bank.blocks.map(topicCard).join('')}</div></section><div class="resource-grid"><a href="#atlas" class="resource-link"><span class="topic-ico">${ic('eye',21)}</span><div><strong>Atlas visual y exploración física</strong><small>49 figuras · anatomía, TC, RM y endoscopia.</small></div>${ic('arrow',16)}</a><a href="#progress" class="resource-link"><span class="topic-ico">${ic('chart',21)}</span><div><strong>Mi progreso</strong><small>Consulta tus resultados y tu recorrido.</small></div>${ic('arrow',16)}</a><a href="#sheets" class="resource-link"><span class="topic-ico">${ic('layers',21)}</span><div><strong>Fichas y mapas de estudio</strong><small>Relaciona conceptos y repasa sus fuentes.</small></div>${ic('arrow',16)}</a><a href="#bank" class="resource-link"><span class="topic-ico">${ic('search',21)}</span><div><strong>Encuentra una respuesta</strong><small>Busca entre las 464 preguntas de tu banco.</small></div>${ic('arrow',16)}</a></div><footer class="bottom-note"><span>${ic('shield',11)} Tu progreso se guarda en este dispositivo.</span><a href="#settings">Banco original y referencias conservadas · ORL Estudio</a></footer>`,'Mi inicio');}
function configCandidates(){return filterBank(bank.questions,state.records,{block:cfg.block,level:cfg.level,format:cfg.type==='card'?'all':'mcq',pool:cfg.pool});}
const opt=(v,t,selected)=>`<option value="${e(v)}" ${String(v)===String(selected)?'selected':''}>${e(t)}</option>`;
function setup(isExam){if(isExam)cfg.type='exam';const available=configCandidates();const count=Math.min(Number(cfg.count),available.length);return shell(`<div class="page-title"><div class="eyebrow">${isExam?'Ponte a prueba':'A tu ritmo'}</div><h1>${isExam?'Un ensayo para el gran día.':'¿Qué vas a estudiar hoy?'}</h1><p>${isExam?'Responde sin consultar las soluciones y revisa tus resultados al terminar.':'Elige un tema y la forma en que quieres practicar.'}</p></div>${resumeBanner()}<div class="two-col"><section class="panel"><h2>${isExam?'Configura tu simulacro':'Prepara tu sesión'}</h2><p>${isExam?'El simulacro utiliza las 94 preguntas de selección simple del banco.':'Todas las respuestas y sus fuentes se conservan como aparecen en tu documento.'}</p>${!isExam?`<div class="mode-grid"><button class="mode-card ${cfg.type==='card'?'active':''}" data-act="set-mode" data-value="card" aria-pressed="${cfg.type==='card'}"><span class="mode-check"></span>${ic('cards',24)}<strong>Tarjetas de repaso</strong><small>464 preguntas. Responde, revela y evalúa cuánto recordabas.</small></button><button class="mode-card ${cfg.type==='mcq'?'active':''}" data-act="set-mode" data-value="mcq" aria-pressed="${cfg.type==='mcq'}"><span class="mode-check"></span>${ic('target',24)}<strong>Selección simple</strong><small>94 preguntas con cuatro opciones y corrección inmediata.</small></button></div>`:''}<div class="form-row"><div class="field"><label for="config-block">Bloque temático</label><select id="config-block" data-config="block">${opt('all','Todos los bloques',cfg.block)}${bank.blocks.map(b=>opt(b.id,b.short,cfg.block)).join('')}</select></div><div class="field"><label for="config-level">Dificultad</label><select id="config-level" data-config="level">${opt('all','Todos los niveles',cfg.level)}${Object.entries(LEVELS).map(([v,t])=>opt(v,t,cfg.level)).join('')}</select></div></div><div class="form-row"><div class="field"><label for="config-pool">Preguntas a incluir</label><select id="config-pool" data-config="pool">${[['all','Todas las preguntas'],['new','Sin repasar'],['errors','Para reforzar'],['saved','Mis favoritas'],['due','Repaso pendiente']].map(([v,t])=>opt(v,t,cfg.pool)).join('')}</select></div><div class="field"><label for="config-count">Tamaño de la sesión</label><select id="config-count" data-config="count">${[10,20,50,94,464].filter(n=>n<=94||cfg.type==='card').map(n=>opt(n,n===464?'Todas las disponibles':n+' preguntas',cfg.count)).join('')}</select></div></div>${isExam?`<div class="form-row"><div class="field"><label for="config-minutes">Tiempo disponible</label><select id="config-minutes" data-config="minutes">${[10,20,30,60,90].map(n=>opt(n,n+' minutos',cfg.minutes)).join('')}</select></div></div><p class="exam-note">El tiempo continúa si cierras la aplicación. Puedes cambiar tus respuestas antes de finalizar. Las preguntas sin responder cuentan en la puntuación final.</p>`:'<p class="hint">Las preguntas se presentan al azar. En las tarjetas, la autoevaluación se registra por separado de los aciertos de selección.</p>'}<div class="setup-footer"><strong>${count}<small>preguntas en esta sesión</small></strong><button class="btn" data-act="start" ${!count?'disabled':''}>${isExam?'Comenzar simulacro':'Comenzar sesión'} ${ic('arrow',15)}</button></div><p class="count-hint">${available.length} disponibles con estos filtros.${available.length<Number(cfg.count)?' Se utilizarán todas las disponibles.':''}</p></section><aside class="panel"><h2>${isExam?'Como en el examen':'Un repaso que se adapta a ti'}</h2><ul class="feature-list">${(isExam?[["clock","A tu tiempo","Elige la duración y administra los minutos entre las preguntas."],["bookmark","Recorre el simulacro","Vuelve a cualquier pregunta con el mapa de navegación."],["chart","Resultados claros","Consulta aciertos, errores y omisiones. Revisa cada respuesta y su fuente."]]:[["eye","Recuerda antes de mirar","Puedes escribir tu respuesta o decirla en voz alta antes de revelar la solución."],["repeat","Vuelve a lo que cuesta","Las tarjetas difíciles y las respuestas incorrectas pasan a tus repasos."],["book","Vuelve al libro","Cada respuesta conserva la fuente y el acceso a las referencias del bloque."]]).map(([i,t,p])=>`<li>${ic(i,20)}<div><strong>${t}</strong>${p}</div></li>`).join('')}</ul><div class="mini-kpi"><strong>Tu banco completo</strong><br>181 básicas · 189 intermedias · 94 avanzadas.<br>370 abiertas y 94 de selección simple.</div></aside></div>`,isExam?'Simulacro':'Practicar');}
function startSession(ids,type=cfg.type){if(!ids.length){toast('No hay preguntas disponibles con estos filtros.');return;}const build=()=>{state.session={type,ids:shuffle(ids),pos:0,answers:{},recorded:{},revealed:{},drafts:{},ratings:{},started:Date.now(),deadline:type==='exam'?Date.now()+Number(cfg.minutes)*60000:null,done:false};persist();go('session');};if(state.session&&!state.session.done){modal('¿Empezar una nueva sesión?','<p>Los repasos ya realizados se conservan. La sesión pendiente se sustituirá por la nueva.</p>',[{label:'Conservar sesión',action:'close-modal'},{label:'Empezar nueva',action:'replace-session',primary:true}]);pendingAction=build;}else build();}
let pendingAction=null;
function sessionView(){const s=state.session;if(!s)return shell(`<div class="empty">${ic('cards',35)}<h2>Elige tu primera sesión</h2><p>Prepara unas tarjetas de repaso o practica las preguntas de selección.</p><a href="#practice" class="btn">Ir a practicar ${ic('arrow',15)}</a></div>`,'Practicar');if(s.done)return resultView();const q=byId.get(s.ids[s.pos]);const answer=s.answers[q.id];const isExam=s.type==='exam';const isCard=s.type==='card';const revealed=s.revealed[q.id];const correct=answer===q.correct;const answered=Object.keys(s.answers).length;let body='';
 if(isCard){body=`${q.type==='mcq'?`<div class="options" style="margin-bottom:20px">${q.options.map(o=>`<div class="option"><span class="letter">${o.key}</span><span>${e(o.text)}</span></div>`).join('')}</div>`:''}${!revealed?`<label class="answer-draft-label" for="answer-draft">Tu respuesta (opcional, solo para comparar)</label><textarea id="answer-draft" class="draft" maxlength="8000" placeholder="Escribe lo que recuerdas antes de ver la solución…">${e(s.drafts[q.id]||'')}</textarea><div class="reveal">${ic('cards',31)}<strong>Tómate un momento para recordar.</strong><small>Responde en voz alta o por escrito.<br>Después compara con el banco.</small><button class="btn" data-act="reveal">${ic('eye',16)} Revelar respuesta</button></div>`:`${s.drafts[q.id]?`<div class="exam-note"><strong>Tu respuesta</strong><br>${e(s.drafts[q.id]).replace(/\n/g,'<br>')}</div>`:''}<section class="response-box"><h3>Respuesta del banco</h3>${answerHtml(q)}</section><p class="rating-label">¿Cuánto recordabas? <span class="subtle" style="font-weight:400">Autoevaluación</span></p><div class="rating-grid">${[['again','No la sabía','En 10 minutos'],['hard','Con dificultad','En 1 día'],['good','La sabía','Desde 3 días'],['easy','Muy fácil','Desde 7 días']].map(([v,l,t])=>`<button class="rating-btn" data-act="rate" data-value="${v}">${l}<small>${t}</small></button>`).join('')}</div>`}`;}
 else {body=`<div class="options" role="group" aria-label="Opciones de respuesta">${q.options.map(o=>{let cls=answer===o.key?'selected':'';if(!isExam&&answer){if(o.key===q.correct)cls='correct';else if(o.key===answer)cls='incorrect';}return `<button class="option ${cls}" data-act="answer" data-value="${o.key}" ${!isExam&&answer?'disabled':''} aria-pressed="${answer===o.key}"><span class="letter">${o.key}</span><span>${e(o.text)}</span>${!isExam&&answer&&o.key===q.correct?ic('check',17):!isExam&&answer&&o.key===answer?ic('close',17):''}</button>`;}).join('')}</div>${!isExam&&answer?`<section class="response-box ${correct?'':'wrong'}"><h3>${correct?'¡Respuesta correcta!':'Una oportunidad para reforzar'}</h3>${answerHtml(q)}</section>`:''}`;}
 const label=isExam?'Simulacro':isCard?'Tarjetas de repaso':'Selección simple';return shell(`<div class="session-shell"><div class="session-heading"><button class="icon-btn" data-act="pause" aria-label="Volver al inicio y conservar sesión">${ic('back',19)}</button><div><h1>${label}</h1><small>${e(bank.blocks[q.block-1].short)} · ${isCard?'Recuerda, compara, repasa.':isExam?'Las soluciones aparecen al finalizar.':'Una sola respuesta correcta.'}</small></div>${isExam?`<div id="timer" class="timer">${ic('clock',14)}<span id="timer-value">${timeLeft(s.deadline)}</span></div>`:''}</div><div class="session-bar"><span>Pregunta ${s.pos+1} de ${s.ids.length}</span><div class="progress-track"><i style="width:${s.pos/s.ids.length*100}%"></i></div><span>${isExam?answered+' respondidas':Object.keys(s.recorded).length+' repasadas'}</span></div><section class="question-panel" aria-label="Pregunta ${q.id}"><div class="question-top"><div class="tags">${tag(q)}${formatTag(q)}</div><button class="icon-btn ${state.records[q.id]?.saved?'saved':''}" data-act="save" data-id="${q.id}" aria-label="${state.records[q.id]?.saved?'Quitar de favoritas':'Guardar en favoritas'}" aria-pressed="${Boolean(state.records[q.id]?.saved)}">${ic('bookmark',18)}</button></div><div class="question-topic">${e(q.topic)} <span class="subtle">· Nº ${q.id}</span></div><h2 class="question-text">${e(q.prompt)}</h2>${body}<div class="session-actions">${isExam?`<button class="btn secondary small" data-act="exam-prev" ${s.pos===0?'disabled':''}>${ic('back',14)} Anterior</button><button class="btn small" data-act="${s.pos===s.ids.length-1?'confirm-finish':'next'}">${s.pos===s.ids.length-1?'Finalizar':'Siguiente'} ${ic('arrow',14)}</button>`:`<button class="btn ghost small" data-act="next">${!isCard&&answer?'Continuar después':'Omitir por ahora'}</button>${!isCard&&answer?`<button class="btn small" data-act="next">${s.pos===s.ids.length-1?'Ver resultado':'Siguiente pregunta'} ${ic('arrow',14)}</button>`:'<small>Tu progreso se guarda al responder.</small>'}`}</div></section>${isExam?`<div class="question-map" aria-label="Navegar por preguntas">${s.ids.map((id,i)=>`<button class="${s.answers[id]?'answered':''} ${i===s.pos?'current':''}" data-act="exam-jump" data-value="${i}" aria-label="Pregunta ${i+1}${s.answers[id]?', respondida':''}" ${i===s.pos?'aria-current="step"':''}>${i+1}</button>`).join('')}</div><button class="text-btn" style="margin:20px auto" data-act="confirm-finish">Finalizar y revisar simulacro ${ic('arrow',13)}</button>`:''}</div>`,label);}
function timeLeft(deadline){const s=Math.max(0,Math.ceil((deadline-Date.now())/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function finishSession(){const s=state.session;if(!s||s.done)return;if(s.type==='exam'){for(const id of s.ids){if(s.answers[id]&&!s.recorded[id]){saveReview(id,'mcq',s.answers[id]===byId.get(id).correct);s.recorded[id]=true;}}const scored=scoreExam(s.ids,s.answers,bank.questions);state.history.push({ended:Date.now(),total:scored.total,correct:scored.correct,wrong:scored.wrong,skipped:scored.skipped,percentage:scored.percentage});state.history=state.history.slice(-100);}
 s.done=true;s.ended=Date.now();persist();go('result');}
function resultView(){const s=state.session;if(!s||!s.done)return home();const isCard=s.type==='card';const score=isCard?null:scoreExam(s.ids,s.answers,bank.questions);const reviewed=Object.keys(s.recorded).length;const toReinforce=isCard?s.ids.filter(id=>['again','hard'].includes(s.ratings[id])):score.results.filter(r=>!r.correct).map(r=>r.id);return shell(`<div class="session-shell"><section class="result-hero">${ic(isCard?'cards':'target',30)}<h1>${isCard?'Un paso más en tu preparación.':'Tu sesión, en perspectiva.'}</h1><div class="score">${isCard?reviewed:score.percentage}<small>${isCard?' / '+s.ids.length:'%'}</small></div><p>${isCard?'Tarjetas repasadas. Tu autoevaluación te ayudará a elegir qué reforzar.':`${score.correct} ${score.correct===1?'respuesta correcta':'respuestas correctas'} de ${score.total} preguntas.`}</p><div class="result-stats">${isCard?`<div><strong>${Object.values(s.ratings).filter(r=>r==='good'||r==='easy').length}</strong><small>Las sabías</small></div><div><strong>${toReinforce.length}</strong><small>Para reforzar</small></div><div><strong>${s.ids.length-reviewed}</strong><small>Omitidas</small></div>`:`<div><strong>${score.correct}</strong><small>Aciertos</small></div><div><strong>${score.wrong}</strong><small>Errores</small></div><div><strong>${score.skipped}</strong><small>Sin responder</small></div>`}</div></section><div class="result-actions">${toReinforce.length?`<button class="btn" data-act="retry-session">${ic('repeat',16)} Repasar ${isCard?'las difíciles':'errores y omisiones'}</button>`:''}<a class="btn secondary" href="#practice">Otra sesión ${ic('arrow',14)}</a><a class="btn ghost" href="#home">Volver al inicio</a></div>${toReinforce.length?`<div class="section-head"><div><h2>Lo que merece otro repaso</h2><p>${toReinforce.length} preguntas · Abre cada una para revisar su respuesta.</p></div></div>${toReinforce.map(id=>{const q=byId.get(id);const selected=q.options.find(o=>o.key===s.answers[id]);return `<details class="review-detail"><summary><span class="subtle">${id}.</span> ${e(q.prompt)}</summary><div class="review-body">${!isCard?`<p class="your-answer">Tu respuesta: ${selected?e(selected.key+') '+selected.text):'Sin responder'}</p>`:''}${answerHtml(q)}</div></details>`;}).join('')}`:`<div class="empty">${ic('check',30)}<h2>${isCard?'Buen repaso.':'¡Todas correctas!'}</h2><p>${isCard?'Puedes continuar con nuevas tarjetas o volver a las que ya has estudiado.':'Continúa con otro bloque o practica las preguntas abiertas sin pistas.'}</p></div>`}</div>`,'Resultado de sesión');}
function bankItem(q){const r=state.records[q.id];return `<article class="bank-item"><span class="num">${String(q.id).padStart(3,'0')}</span><div class="bank-item-content"><h3>${e(q.prompt)}</h3><div class="tags">${tag(q)}${formatTag(q)}<span class="tag neutral">${e(bank.blocks[q.block-1].short)}</span>${r?.needsReview?'<span class="tag advanced">Para reforzar</span>':''}</div></div><button class="icon-btn ${r?.saved?'saved':''}" data-act="save" data-id="${q.id}" aria-label="${r?.saved?'Quitar':'Guardar'} pregunta ${q.id} en favoritas" aria-pressed="${Boolean(r?.saved)}">${ic('bookmark',17)}</button><button class="icon-btn open-btn" data-act="view" data-id="${q.id}" aria-label="Ver pregunta ${q.id}">${ic('chevron',17)}</button></article>`;}
function bankView(){const qs=filterBank(bank.questions,state.records,filters);const pages=Math.max(1,Math.ceil(qs.length/20));listPage=Math.max(1,Math.min(listPage,pages));return shell(`<div class="page-title"><div class="eyebrow">Todo tu contenido, organizado</div><h1>Banco de preguntas</h1><p>Busca un concepto, consulta una respuesta o guarda una pregunta para después.</p></div><div class="filters"><div class="search">${ic('search',17)}<input id="bank-search" type="search" value="${e(filters.search)}" placeholder="Buscar preguntas o conceptos…" aria-label="Buscar preguntas"></div><select data-filter="block" id="bank-block" aria-label="Filtrar por bloque">${opt('all','Todos los bloques',filters.block)}${bank.blocks.map(b=>opt(b.id,b.short,filters.block)).join('')}</select><select data-filter="level" id="bank-level" aria-label="Filtrar por dificultad">${opt('all','Todos los niveles',filters.level)}${Object.entries(LEVELS).map(([v,l])=>opt(v,l,filters.level)).join('')}</select><select data-filter="format" id="bank-format" aria-label="Filtrar por formato">${[['all','Todos los formatos'],['open','Abiertas'],['mcq','Selección simple']].map(([v,l])=>opt(v,l,filters.format)).join('')}</select></div><p class="results-line">${qs.length} ${qs.length===1?'pregunta encontrada':'preguntas encontradas'}</p><div class="bank-list">${qs.slice((listPage-1)*20,listPage*20).map(bankItem).join('')||'<div class="empty"><h2>No hay coincidencias</h2><p>Prueba con otra palabra o cambia los filtros.</p></div>'}</div>${pages>1?`<div class="pagination"><button class="btn secondary small" data-act="page" data-value="${listPage-1}" ${listPage===1?'disabled':''}>${ic('back',13)} Anterior</button><span>${listPage} de ${pages}</span><button class="btn secondary small" data-act="page" data-value="${listPage+1}" ${listPage===pages?'disabled':''}>Siguiente ${ic('arrow',13)}</button></div>`:''}`,'Banco de preguntas');}
function reviewView(){const qs=filterBank(bank.questions,state.records,{pool:reviewTab});const labels={errors:'Para reforzar',saved:'Mis favoritas',due:'Repaso pendiente'};return shell(`<div class="page-title"><div class="eyebrow">Vuelve a lo que importa</div><h1>Mis repasos</h1><p>Reúne lo que te cuesta y lo que quieres recordar mejor.</p></div><div class="review-actions">${Object.entries(labels).map(([v,l])=>`<button class="tab-btn ${v===reviewTab?'active':''}" data-act="review-tab" data-value="${v}">${l} <span class="subtle">${filterBank(bank.questions,state.records,{pool:v}).length}</span></button>`).join('')}</div>${qs.length?`<div class="section-head"><div><h2>${qs.length} ${qs.length===1?'pregunta':'preguntas'} para ti</h2><p>${reviewTab==='due'?'Preguntas cuyo intervalo de repaso ya se ha cumplido.':reviewTab==='saved'?'Las preguntas que has guardado en cualquier momento.':'Errores de selección y tarjetas marcadas como difíciles.'}</p></div><button class="btn small" data-act="review-start">${ic('cards',15)} Repasar</button></div><div class="bank-list">${qs.map(bankItem).join('')}</div>`:`<div class="empty">${ic(reviewTab==='saved'?'bookmark':'repeat',35)}<h2>${reviewTab==='saved'?'Tus favoritas empiezan aquí':reviewTab==='due'?'Por ahora, todo al día':'Un espacio para seguir mejorando'}</h2><p>${reviewTab==='saved'?'Toca el marcador de una pregunta para guardarla en esta sección.':reviewTab==='due'?'Las preguntas aparecerán aquí cuando llegue su próximo repaso. Puedes seguir estudiando en cualquier momento.':'Las respuestas incorrectas y las tarjetas difíciles aparecerán aquí después de practicar.'}</p><a href="#practice" class="btn">Practicar ${ic('arrow',15)}</a></div>`}`,'Mis repasos');}
const sheets=[{title:'Pares craneales',subtitle:'Recorrido, funciones y exploración.',icon:'anatomy',ids:[27,29,30,34,35,37,38,39]},{title:'Cuello por planos',subtitle:'Triángulos, fascias y espacios cervicales.',icon:'layers',ids:[41,42,43,45,46,47]},{title:'El oído, por partes',subtitle:'Del pabellón al laberinto.',icon:'ear',ids:[59,60,64,67,72,74,77,80,82]},{title:'Exploración auditiva',subtitle:'Diapasones, audiometría e impedanciometría.',icon:'target',ids:[107,109,110,111,112]},{title:'Desarrollo y embriología',subtitle:'Arcos, bolsas, hendiduras y tiroides.',icon:'child',ids:[54,55,56,57,58,76]},{title:'Mapa de cabeza y cuello',subtitle:'Irrigación, drenaje y niveles ganglionares.',icon:'neck',ids:[11,12,14,19,21,22,49,50,51,52]}];
function sheetsView(){const index=Number(route().params.get('id'));if(route().params.has('id')&&sheets[index])return sheetDetail(sheets[index],index);return shell(`<div class="page-title"><div class="eyebrow">Conecta los conceptos</div><h1>Fichas de estudio</h1><p>Rutas temáticas para consultar y relacionar las respuestas de tu banco.</p></div><div class="sheet-grid">${sheets.map((s,i)=>`<a class="sheet-card" href="#sheets?id=${i}"><div class="topic-ico" style="background:${tints[i]};color:${accents[i]}">${ic(s.icon,23)}</div><h2>${s.title}</h2><p>${s.subtitle}</p><div class="sheet-count"><span>${s.ids.length} conceptos con sus fuentes</span>${ic('arrow',15)}</div></a>`).join('')}</div><p class="hint">Estas fichas agrupan el texto original del banco. Las diferencias entre libros y las referencias se mantienen dentro de cada respuesta.</p>`,'Fichas de estudio');}
function sheetDetail(sheet,index){return shell(`<div class="session-shell"><a class="text-btn" href="#sheets" style="margin-bottom:20px">${ic('back',14)} Todas las fichas</a><div class="page-title"><div class="eyebrow">Ficha de estudio</div><h1>${sheet.title}</h1><p>${sheet.subtitle}</p></div><div class="sheet-intro">${ic('light',16)} Abre cada concepto después de intentar explicarlo. Al final puedes practicar esta ruta completa en tarjetas.</div>${[0,5].includes(index)?visualMap(index===0?27:49):''}<section class="panel">${sheet.ids.filter(id=>!(index===0&&id===27)&&!(index===5&&id===49)).map(id=>{const q=byId.get(id);return `<details class="study-accordion"><summary>${e(q.prompt)}</summary><div>${answerHtml(q)}<div style="height:20px"></div></div></details>`;}).join('')}</section><div class="session-actions"><a href="#sheets" class="btn secondary">Volver a fichas</a><button class="btn" data-act="sheet-start" data-id="${index}">Practicar esta ficha ${ic('arrow',15)}</button></div></div>`,'Fichas de estudio');}
function visualMap(id){const q=byId.get(id);const rows=id===49?q.answer.slice(0,6):q.answer;const notes=id===49?q.answer.slice(6):[];return `<section class="panel visual-panel"><div class="section-head"><div><div class="eyebrow">Mapa interactivo</div><h2>${id===27?'Pares craneales y orificios':'Niveles ganglionares del cuello'}</h2><p>Toca un elemento para revelar su respuesta.</p></div>${ic(id===27?'anatomy':'neck',28)}</div><div class="visual-map">${rows.map(t=>{const split=t.indexOf(':');const label=split>=0?t.slice(0,split):t;const value=split>=0?t.slice(split+1).trim():'';return value?`<details class="map-item"><summary><span>${e(label)}</span>${ic('eye',14)}</summary><p>${e(value)}</p></details>`:`<div class="map-group">${e(label)}</div>`;}).join('')}</div>${notes.map(t=>`<p class="hint">${e(t)}</p>`).join('')}<div class="source"><strong>Fuente del banco · Pregunta ${id}</strong>${q.sources.map(e).join('<br>')}<br><button class="text-btn" data-act="references" data-id="${q.block}">Ver referencias completas ${ic('arrow',12)}</button></div></section>`;}
function progressView(){const stats=summarize(bank.questions,state);const today=new Date();const days=Array.from({length:7},(_,i)=>{const date=new Date(today.getFullYear(),today.getMonth(),today.getDate()-6+i,12);return {label:new Intl.DateTimeFormat('es',{weekday:'short'}).format(date).slice(0,2),n:state.activity[localDate(date.getTime())]||0};});const max=Math.max(state.goal,...days.map(d=>d.n));return shell(`<div class="page-title"><div class="eyebrow">Mira todo lo que avanzas</div><h1>Mi progreso</h1><p>Las estadísticas de selección y la autoevaluación de tarjetas se registran por separado.</p></div><div class="stats-grid"><div class="stat"><div class="stat-icon">${ic('book',18)}</div><div><b>${stats.reviewed}<em> / 464</em></b><span>Preguntas repasadas</span></div></div><div class="stat"><div class="stat-icon">${ic('target',18)}</div><div><b>${stats.accuracy===null?'—':stats.accuracy+'%'}</b><span>${stats.attempts} intentos de selección</span></div></div><div class="stat"><div class="stat-icon">${ic('cards',18)}</div><div><b>${Object.values(state.records).filter(r=>r.lastKind==='card'&&['good','easy'].includes(r.lastRating)).length}</b><span>Tarjetas que sabías</span></div></div><div class="stat"><div class="stat-icon">${ic('clock',18)}</div><div><b>${state.history.length}</b><span>Simulacros terminados</span></div></div></div><div class="two-col"><section class="panel"><h2>Tu recorrido por bloques</h2><p>Preguntas únicas que has repasado al menos una vez.</p><div class="block-progress">${bank.blocks.map(b=>{const n=bank.questions.filter(q=>q.block===b.id&&state.records[q.id]?.reviews).length;const pct=Math.round(n/b.count*100);return `<div><div class="block-progress-head"><span>${e(b.short)}</span><small>${n} / ${b.count} · ${pct}%</small></div><div class="progress-track"><i style="width:${pct}%;background:${accents[b.id-1]}"></i></div></div>`;}).join('')}</div></section><section class="panel"><h2>Esta semana</h2><p>Repasos realizados cada día, incluyendo repeticiones.</p><div class="chart-week" role="img" aria-label="Últimos siete días: ${days.map(d=>d.label+' '+d.n+' repasos').join(', ')}">${days.map(d=>`<div class="day-column"><b>${d.n}</b><div class="bar" style="height:${Math.max(3,d.n/max*105)}px"></div><small>${e(d.label)}</small></div>`).join('')}</div><div class="mini-kpi">Meta diaria: <strong>${state.goal} repasos</strong>.<br>Puedes ajustarla en <a href="#settings" style="text-decoration:underline">Ajustes</a>.</div></section></div><section class="panel" style="margin-top:22px"><h2>Historial de simulacros</h2>${state.history.length?`<table class="history-table"><thead><tr><th>Fecha</th><th>Preguntas</th><th>Aciertos</th><th>Errores</th><th>Omitidas</th><th>Resultado</th></tr></thead><tbody>${state.history.slice(-20).reverse().map(h=>`<tr><td>${new Intl.DateTimeFormat('es',{day:'2-digit',month:'2-digit'}).format(h.ended)}</td><td>${h.total}</td><td>${h.correct}</td><td>${h.wrong}</td><td>${h.skipped}</td><td><strong>${h.percentage}%</strong></td></tr>`).join('')}</tbody></table>`:'<p class="hint">Aquí aparecerán tus resultados cuando completes el primer simulacro.</p>'}</section>`,'Mi progreso');}
function referencesView(block){const b=bank.blocks[block-1];return `<p class="reference-header">${e(b.title)}</p><p>Referencias del documento original, conservadas en su formato bibliográfico.</p><ul class="reference-list">${b.references.map(r=>`<li>${e(r)}</li>`).join('')}</ul>`;}
function settingsView(){return shell(`<div class="page-title"><div class="eyebrow">Tu espacio, a tu manera</div><h1>Ajustes y respaldo</h1><p>Instala la app, ajusta tu meta y conserva una copia de tus avances.</p></div><div class="settings-stack">${profileSummary()}<section class="panel"><h2>Tu estudio</h2><div class="settings-row"><div><strong>Meta diaria</strong><p>Cuenta cada repaso realizado, incluyendo las repeticiones.</p></div><select id="daily-goal" aria-label="Meta de repasos diarios">${[10,20,30,50,100].map(n=>opt(n,n+' repasos',state.goal)).join('')}</select></div><div class="settings-row"><div><strong>Instalar en Android</strong><p>Abre esta página en Chrome y añádela como aplicación.</p></div><button class="btn secondary small" data-act="install">${ic('download',15)} Instalar app</button></div><div class="settings-row"><div><strong>Estudiar sin conexión</strong><p id="offline-settings">${offlineReady?'La aplicación y el banco están descargados en este navegador.':navigator.onLine?'Se está preparando la descarga. Mantén la aplicación abierta unos instantes.':'Conecta este dispositivo una vez para descargar la aplicación.'}</p></div><span class="tag ${offlineReady?'':'neutral'}">${offlineReady?'Disponible':'Pendiente'}</span></div></section>${atlasUI.offlinePanel()}<section class="panel"><h2>Conserva tu progreso</h2><p>Los avances se guardan en este navegador. Para llevarlos a otro dispositivo o protegerlos antes de borrar sus datos, exporta una copia.</p><div class="settings-row"><div><strong>Exportar copia</strong><p>Descarga tu perfil, estadísticas, favoritos, repaso visual e historial de simulacros.</p></div><button class="btn secondary small" data-act="export">${ic('download',15)} Exportar</button></div><div class="settings-row"><div><strong>Importar copia</strong><p>Restaura una copia anterior. Sustituye el perfil y el progreso de este dispositivo.</p></div><button class="btn secondary small" data-act="import">${ic('upload',15)} Importar</button><input type="file" class="file-input" id="backup-input" accept=".json,application/json" aria-label="Seleccionar copia de progreso"></div></section><section class="panel"><h2>Acerca del contenido</h2><p><strong>${e(bank.title)}</strong><br>464 preguntas · 8 bloques · 181 básicas, 189 intermedias y 94 avanzadas.</p><p class="hint">Las 94 preguntas de selección conservan sus cuatro opciones y su clave original. Las 370 abiertas se estudian como tarjetas. Las fichas reúnen respuestas del mismo documento. El atlas incorpora 49 figuras y sus leyendas del PDF de 224 páginas.</p><p class="hint">${e(bank.contentStatus)} Las fuentes y las diferencias entre autores se conservan. El atlas conserva los rótulos y las notas del documento. Las vistas de exploración física conservan su fuente original. No se han añadido respuestas médicas nuevas.</p><div class="pill-row">${bank.blocks.map(b=>`<button class="pill" data-act="references" data-id="${b.id}">${e(b.short)} ${ic('book',11)}</button>`).join('')}</div></section><section class="panel"><h2>Reiniciar preparación</h2><p>Elimina el progreso, las favoritas y el historial de este dispositivo. Puedes exportar una copia antes.</p><button class="btn secondary small" style="margin-top:18px;color:#a35c4b" data-act="reset">Reiniciar mi progreso</button></section></div>`,'Ajustes y respaldo');}
function render(preserve=false){if(!bank)return;const active=preserve?document.activeElement:null;const id=active?.id;let selection=null;try{if(active?.selectionStart!==undefined)selection=[active.selectionStart,active.selectionEnd];}catch{}const r=route();const views={home,atlas:()=>atlasUI.render('atlas',r.params),exploration:()=>atlasUI.render('exploration',r.params),practice:()=>setup(false),exam:()=>setup(true),session:sessionView,result:resultView,bank:bankView,review:reviewView,sheets:sheetsView,progress:progressView,settings:settingsView};$('#app').innerHTML=(views[r.name]||home)();document.title=`${({home:'Inicio',atlas:'Atlas visual',exploration:'Exploración física',practice:'Practicar',exam:'Simulacro',session:'Sesión',result:'Resultados',bank:'Banco',review:'Mis repasos',sheets:'Fichas',progress:'Progreso',settings:'Ajustes'})[r.name]||'Inicio'} · ORL Estudio`;if(r.name==='atlas'||r.name==='settings')void atlasUI.checkCache();if(id&&preserve){const el=document.getElementById(id);if(el){el.focus({preventScroll:true});if(selection)try{el.setSelectionRange(...selection);}catch{}}}}
function showQuestion(id){const q=byId.get(id);modal(`Pregunta ${id}`,`<div class="tags">${tag(q)}${formatTag(q)}</div><p style="font-size:15px;color:var(--ink);font-weight:550">${e(q.prompt)}</p>${q.type==='mcq'?`<div class="exam-note">${q.options.map(o=>`${o.key}) ${e(o.text)}`).join('<br>')}</div>`:''}<details class="study-accordion"><summary>Revelar respuesta</summary>${answerHtml(q)}</details>`);}
function exportBackup(){const contents={app:'orl-estudio',schema:1,exportedAt:new Date().toISOString(),state:{...state,session:null}};const blob=new Blob([JSON.stringify(contents,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ORL_Estudio_progreso_${localDate()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Copia de progreso descargada.');}
async function importBackup(file){try{if(!file||file.size>3000000)throw Error('Selecciona una copia JSON de menos de 3 MB.');const cleaned=parseBackup(JSON.parse(await file.text()),bank.questions);modal('¿Restaurar esta copia?',`<p>La copia contiene ${Object.values(cleaned.records).filter(r=>r.reviews).length} preguntas repasadas y ${cleaned.history.length} simulacros. Sustituirá el perfil y el progreso actual de este dispositivo.</p>`,[{label:'Cancelar',action:'close-modal'},{label:'Restaurar copia',action:'confirm-import',primary:true}]);pendingAction=()=>{state=cleaned;persist();render();toast('Tu progreso se ha restaurado.');};}catch(err){toast(err.message||'No se pudo leer la copia.');}}
async function install(){if(matchMedia('(display-mode: standalone)').matches){modal('Ya estás usando la aplicación','<p>ORL Estudio ya está abierto como una aplicación instalada.</p>');return;}if(deferredInstall){await deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;return;}modal('Lleva ORL Estudio contigo',`<p>En tu teléfono Android:</p><ol><li>Abre el enlace de esta aplicación en <strong>Google Chrome</strong>.</li><li>Abre el menú <strong>⋮</strong> y toca <strong>Instalar aplicación</strong> o <strong>Añadir a pantalla de inicio</strong>.</li><li>Confirma y abre ORL Estudio desde su icono.</li></ol><p>Para estudiar sin conexión, abre la app con internet y comprueba en Ajustes que el banco está disponible sin conexión. El progreso se guarda en cada dispositivo; usa las copias para trasladarlo.</p>`);}
document.addEventListener('click',async event=>{const atlasButton=event.target.closest('[data-atlas-act]');if(atlasButton&&!atlasButton.disabled){if(atlasUI.click(atlasButton))render(true);return;}const button=event.target.closest('[data-act]');if(!button||button.disabled)return;const action=button.dataset.act;const id=Number(button.dataset.id),value=button.dataset.value;const s=state.session;try{switch(action){case'close-modal':closeModal();break;case'profile':editProfile();break;case'profile-skip':state.profileOnboarded=true;persist();closeModal();render();break;case'install':await install();break;case'set-mode':cfg.type=value;render(true);break;case'start':startSession(shuffle(configCandidates()).slice(0,Number(cfg.count)).map(q=>q.id),cfg.type);break;case'replace-session':case'confirm-import':{const action=pendingAction;pendingAction=null;closeModal();action?.();break;}case'reveal':if(s&&!s.done){s.revealed[s.ids[s.pos]]=true;persist();render();}break;case'rate':if(s&&!s.done&&s.type==='card'){const qid=s.ids[s.pos];if(!s.recorded[qid]){saveReview(qid,'card',null,value);s.recorded[qid]=true;s.ratings[qid]=value;}advance();}break;case'answer':if(s&&!s.done&&s.type!=='card'&&['A','B','C','D'].includes(value)){const qid=s.ids[s.pos];if(s.type!=='exam'&&s.answers[qid])break;s.answers[qid]=value;if(s.type==='mcq'&&!s.recorded[qid]){saveReview(qid,'mcq',value===byId.get(qid).correct);s.recorded[qid]=true;}persist();render(true);}break;case'next':advance();break;case'exam-prev':if(s?.type==='exam'&&s.pos>0){s.pos--;persist();render();}break;case'exam-jump':if(s?.type==='exam'&&Number(value)>=0&&Number(value)<s.ids.length){s.pos=Number(value);persist();render();}break;case'pause':go('home');break;case'confirm-finish':if(s?.type==='exam'&&!s.done){const unanswered=s.ids.length-Object.keys(s.answers).length;modal('¿Finalizar el simulacro?',`<p>${unanswered?`Quedan ${unanswered} preguntas sin responder. Contarán como omisiones en tu resultado.`:'Has respondido todas las preguntas.'} Al finalizar podrás consultar las respuestas y sus fuentes.</p>`,[{label:'Seguir respondiendo',action:'close-modal'},{label:'Ver mi resultado',action:'finish-exam',primary:true}]);}break;case'finish-exam':closeModal();finishSession();break;case'retry-session':if(s?.done){const ids=s.type==='card'?s.ids.filter(id=>['again','hard'].includes(s.ratings[id])):scoreExam(s.ids,s.answers,bank.questions).results.filter(r=>!r.correct).map(r=>r.id);if(ids.length)startSession(ids,s.type==='card'?'card':'mcq');}break;case'save':if(byId.has(id)){const old=state.records[id]||{};state.records[id]={...old,saved:!old.saved};persist();render(true);toast(state.records[id].saved?'Pregunta guardada en favoritas.':'Pregunta retirada de favoritas.');}break;case'view':showQuestion(id);break;case'references':if(bank.blocks[id-1])modal('Referencias del bloque '+id,referencesView(id));break;case'page':listPage=Number(value);render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'});break;case'review-tab':reviewTab=value;render(true);break;case'review-start':startSession(filterBank(bank.questions,state.records,{pool:reviewTab}).map(q=>q.id),'card');break;case'sheet-start':startSession(sheets[id].ids,'card');break;case'export':exportBackup();break;case'import':$('#backup-input').click();break;case'reset':modal('¿Reiniciar tu progreso?','<p>Se borrarán tus repasos, favoritas, historial y sesión pendiente de este dispositivo. El banco de preguntas se conserva. Exporta una copia si quieres recuperar tus avances más adelante.</p>',[{label:'Cancelar',action:'close-modal'},{label:'Reiniciar',action:'confirm-reset',danger:true}]);break;case'confirm-reset':state=resetStudyProgress(state);persist();closeModal();go('home');render();toast('Tu preparación empieza de nuevo.');break;}}catch(err){console.error(err);toast('No se pudo completar la acción. Tu progreso anterior se conserva.');}});
function advance(){const s=state.session;if(!s||s.done)return;if(s.pos<s.ids.length-1){s.pos++;persist();render();window.scrollTo({top:0,behavior:'smooth'});}else if(s.type!=='exam')finishSession();}
document.addEventListener('error',event=>{const image=event.target;if(image instanceof HTMLImageElement&&image.hasAttribute('data-atlas-image'))image.closest('.atlas-image-wrap')?.classList.add('image-failed');},true);
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.atlasFilter){atlasUI.setFilter(el.dataset.atlasFilter,el.value);render(true);}if(el.dataset.config){cfg[el.dataset.config]=el.value;render(true);}if(el.dataset.filter){filters[el.dataset.filter]=el.value;listPage=1;render(true);}if(el.id==='daily-goal'){state.goal=Number(el.value);persist();toast('Meta diaria actualizada.');}if(el.id==='backup-input'&&el.files?.[0])importBackup(el.files[0]);});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='atlas-search'){atlasUI.setFilter('search',el.value);render(true);}if(el.id==='bank-search'){filters.search=el.value;listPage=1;render(true);}if(el.id==='answer-draft'&&state.session){state.session.drafts[state.session.ids[state.session.pos]]=el.value;persist();}});
window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();document.getElementById('atlas-zoom-dialog')?.close();const r=route();if(r.name==='practice'||r.name==='exam'){cfg={type:r.name==='exam'?'exam':'card',block:r.params.get('block')||'all',pool:r.params.get('pool')||'all',level:'all',count:20,minutes:20};}if(r.name==='review')reviewTab=r.params.get('tab')==='saved'?'saved':'errors';render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;});
window.addEventListener('appinstalled',()=>{deferredInstall=null;toast('ORL Estudio ya está instalado.');});
window.addEventListener('online',()=>updateOffline());window.addEventListener('offline',()=>updateOffline());
setInterval(()=>{const s=state.session;if(s?.type==='exam'&&!s.done){if(Date.now()>=s.deadline){if($('#modal').open)closeModal();finishSession();toast('El tiempo terminó. Aquí tienes tu resultado.');}else if($('#timer-value')){$('#timer-value').textContent=timeLeft(s.deadline);$('#timer').classList.toggle('urgent',s.deadline-Date.now()<120000);}}},1000);
async function updateOffline(){try{const reg=await navigator.serviceWorker?.getRegistration(APP_ROOT.href);if(reg?.active){const channel=new MessageChannel();channel.port1.onmessage=event=>{offlineReady=event.data?.ready===true;const el=$('#offline-status');if(el)el.textContent=offlineReady?'Banco sin conexión':navigator.onLine?'En línea':'Sin conexión';if(route().name==='settings'){render(true);void atlasUI.checkCache();}};reg.active.postMessage({type:'CHECK_READY'},[channel.port2]);}}catch{offlineReady=false;}}
async function boot(){try{const atlasPromise=fetch(new URL('atlas.json',APP_ROOT)).then(r=>r.ok?r.json():null).catch(()=>null);const response=await fetch(new URL('bank.json',APP_ROOT));if(!response.ok)throw Error('No se pudo descargar el banco');bank=await response.json();atlasCatalog=await atlasPromise;byId=new Map(bank.questions.map(q=>[q.id,q]));loadState();const r=route();if(['practice','exam'].includes(r.name)){cfg.type=r.name==='exam'?'exam':'card';cfg.block=r.params.get('block')||'all';cfg.pool=r.params.get('pool')||'all';}if(r.name==='review'&&r.params.get('tab')==='saved')reviewTab='saved';render();if(!state.profileOnboarded)editProfile(true);if('serviceWorker'in navigator){try{const reg=await navigator.serviceWorker.register(new URL('sw.js',APP_ROOT),{scope:APP_ROOT.href,updateViaCache:'none'});await navigator.serviceWorker.ready;await updateOffline();navigator.serviceWorker.addEventListener('controllerchange',()=>updateOffline());if(reg.waiting)reg.waiting.postMessage({type:'SKIP_WAITING'});}catch(err){console.warn('Offline no disponible',err);if(route().name==='settings'){render(true);void atlasUI.checkCache();}}}}catch(err){$('#app').innerHTML=`<main class="boot"><div class="boot-mark">orl<span>·</span></div><p>No se pudo abrir el banco de preguntas.</p><p>Comprueba la conexión y vuelve a intentarlo.</p><button class="btn" onclick="location.reload()">Volver a intentar</button></main>`;console.error(err);}}
boot();
